// ============================================================
//  CLM AFTER BUSINESS RULE
//  Table  : x_birl3_clm_clm_new_credit_request
//  When   : After Insert (state = Submitted)
//  Purpose: 1. Save approver sequence JSON to the record
//           2. Notify first approver
// ============================================================

(function executeRule(current, previous) {

    if (current.customer_type + '' !== 'Trade') return;
    if (current.state         + '' !== 'Submitted') return;

    try {
        // ── 1. Read sequence built by Before BR ─────────────────
        var seqJson = gs.getSession().getClientData('clm_approver_sequence');
        gs.info('CLM After BR: got from session = [' + seqJson + ']');

        if (!seqJson || seqJson === '' || seqJson === 'null') {
            gs.error('CLM After BR: no sequence in session, skipping');
            return;
        }

        // ── 2. Write sequence + role-field values to record ─────
        var updateGr = new GlideRecord('x_birl3_clm_clm_new_credit_request');
        if (!updateGr.get(current.sys_id + '')) {
            gs.error('CLM After BR: record not found: ' + current.sys_id);
            return;
        }

        // Save the sequence JSON
        updateGr.setValue('u_approver_sequence',      seqJson);
        updateGr.setValue('u_current_approver_order', 1);

        // ── 3. Also write individual role fields via After BR ────
        //    (Belt-and-suspenders: Before BR sets them on current,
        //     but After BR re-reads the resolver to guarantee they
        //     are persisted on the saved record.)

        var resolver = new CLMUserResolver();
        var router   = new CLMApprovalRouter();
        var segment  = updateGr.segment  + '';
        var region   = updateGr.region   + '';
        var zone     = updateGr.zone     + '';
        var depot    = updateGr.depot    + '';

        var ROLE_TO_FIELD = {
            // Cement
            'TSH':              'u_approver_tsh',
            'RHM':              'u_approver_rhm',
            'ZHM':              'u_approver_zhm',
            'ZCH':              'u_approver_zch',
            'HO':               'u_approver_ho',
            'NSH':              'u_approver_nsh',
            'NSH_CCH':          'u_approver_nsh_cch',
            'CMO':              'u_approver_cmo',
            'CMO_CFO':          'u_approver_cmo_cfo',
            'CFO':              'u_approver_cfo',
            'MD':               'u_approver_md',
            // RMC
            'TSM':              'u_approver_tsm',
            'RH_CH_RMC':        'u_approver_rh_ch_rmc',
            'ZH_RMC':           'u_approver_zh_rmc',
            'HEAD_RMC':         'u_approver_head_rmc',
            'HEAD_KEY_CH_RMC':  'u_approver_head_key_ch_rmc',
            'HEAD_KEY_CCH':     'u_approver_head_key_cch',
            'BH':               'u_approver_bh',
            'BH_CFO':           'u_approver_bh_cfo',
            // BPD
            'TSH_BPD':          'u_approver_tsh_bpd',
            'ZH_BPD':           'u_approver_zh_bpd',
            'HSBPD':            'u_approver_hsbpd',
            'HBPD':             'u_approver_hbpd',
            'CCH_HBPD':         'u_approver_cch_hbpd'
        };

        // Parse sequence and set each role field
        var seq = [];
        try { seq = JSON.parse(seqJson); } catch(e) {}

        for (var i = 0; i < seq.length; i++) {
            var step      = seq[i];
            var fieldName = ROLE_TO_FIELD[step.role];
            if (fieldName && step.user_sys_id) {
                updateGr.setValue(fieldName, step.user_sys_id);
                gs.info('CLM After BR: set ' + fieldName + ' = ' + step.user_sys_id +
                        ' (' + step.role + ')');
            }
        }

        updateGr.setWorkflow(false);
        updateGr.autoSysFields(false);
        updateGr.update();

        gs.info('CLM After BR: SAVED sequence + role fields for ' + updateGr.request_number);

        // ── 4. Clear session ─────────────────────────────────────
        gs.getSession().putClientData('clm_approver_sequence', '');

        // ── 5. Notify first approver ─────────────────────────────
        if (seq.length > 0 && seq[0].user_sys_id) {
            var seqHelper = new CLMSequentialApproval();
            seqHelper._sendApprovalNotification(
                current.sys_id + '',
                seq[0].user_sys_id,
                seq[0].role
            );
            gs.info('CLM After BR: notified first approver ' + seq[0].role);
        }

    } catch (e) {
        gs.error('CLM After BR ERROR: ' + e.message);
    }

})(current, previous);
